{"file_path":"_probe_results.gd","content":"extends Node
# 临时验证探针：开一局 → 触发结算页 → 打印关键 rect + 截图。用完即删。

var _bm: Node = null
var _panel: CanvasLayer = null
var _f := 0

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	_bm = ps.instantiate()
	add_child(_bm)

func _process(_d: float) -> void:
	_f += 1
	match _f:
		120:
			_bm._start_game("亚瑟")
		240:
			_bm.winner = Config.Team.PLAYER
			_bm._show_game_over()
			_panel = _find_panel()
			print("[PROBE] viewport=", get_viewport().get_visible_rect().size)
		275:
			_dump_overview("WIN")
			_shot("user://probe_win_overview.png")
		300:
			if _panel: _panel._switch_tab(1)
		325:
			_dump_data()
			_shot("user://probe_win_data.png")
		340:
			if _panel: _panel._switch_tab(2)
		365:
			_shot("user://probe_win_replay.png")
		380:
			if _panel && is_instance_valid(_panel):
				_panel.queue_free()
			_bm.winner = Config.Team.ENEMY
			_bm._show_game_over()
			_panel = _find_panel()
		415:
			_shot("user://probe_lose_overview.png")
		430:
			get_tree().quit()

func _find_panel() -> CanvasLayer:
	for c in _bm.get_children():
		if c is ResultsPanel:
			return c
	return null

func _r(c: Control) -> String:
	if c == null || !is_instance_valid(c) || !c.is_inside_tree():
		return "null"
	var g := c.get_global_rect()
	return "pos=(%d,%d) size=(%d,%d)" % [int(g.position.x), int(g.position.y), int(g.size.x), int(g.size.y)]

func _child(n: Node, i: int) -> Control:
	if n == null || !is_instance_valid(n) || n.get_child_count() <= i:
		return null
	var c = n.get_child(i)
	return c if c is Control else null

func _dump_overview(tag: String) -> void:
	if _panel == null: return
	var mv: Control = _child(_panel, 1)
	var top: Control = _child(mv, 0)
	var tabs: Control = _child(mv, 1)
	var content: Control = _child(mv, 2)
	var scroll: Control = _child(_child(content, 0), 0)
	var vwrap: Control = _child(scroll, 0)
	var hbox: Control = _child(vwrap, 0)
	var blue: Control = _child(hbox, 0)
	var vs: Control = _child(hbox, 1)
	var red: Control = _child(hbox, 2)
	var card: Control = _child(blue, 1)
	var strip: Control = _child(blue, 0)
	print("[PROBE ", tag, "] main_vbox ", _r(mv))
	print("[PROBE ", tag, "] top_bar ", _r(top), " play_again ", _r(_child(top, 3)), " return ", _r(_child(top, 4)))
	print("[PROBE ", tag, "] tab_bar ", _r(tabs), " tab0 ", _r(_child(tabs, 0)), " tab1 ", _r(_child(tabs, 1)), " tab2 ", _r(_child(tabs, 2)))
	print("[PROBE ", tag, "] content ", _r(content), " hbox ", _r(hbox))
	print("[PROBE ", tag, "] blue_col ", _r(blue), " vs_col ", _r(vs), " red_col ", _r(red))
	print("[PROBE ", tag, "] team_header ", _r(strip), " hero_card#0 ", _r(card))
	var bg: Control = _child(_panel, 0)
	print("[PROBE ", tag, "] bg_layer ", _r(bg), " bg_child_count=", bg.get_child_count() if bg else -1)

func _dump_data() -> void:
	var content: Control = _child(_child(_panel, 1), 2)
	var root: Control = _child(_child(content, 1), 0)
	var scroll: Control = _child(root, 1)
	var vwrap: Control = _child(scroll, 0)
	var mh: Control = _child(vwrap, 0)
	var lcol: Control = _child(mh, 0)
	var rcol: Control = _child(mh, 2)
	var grid: Control = _child(lcol, 1)
	var row: Control = _child(grid, 1)
	print("[PROBE DATA] data_root ", _r(root), " main_hbox ", _r(mh))
	print("[PROBE DATA] left_col ", _r(lcol), " right_col ", _r(rcol))
	print("[PROBE DATA] grid ", _r(grid), " row0 ", _r(row), " row_cells=", row.get_child_count() if row else -1)
	if row:
		for i in range(row.get_child_count()):
			print("[PROBE DATA]  cell", i, " ", _r(_child(row, i)))

func _shot(p: String) -> void:
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png(p)
	print("[PROBE] shot ", p, " ", img.get_size())
"}

