import colorsys
im = Image.open('probe_win_overview.png').convert('RGB')
W, H = im.size
cats = {'green': (0,0,0,0), 'cyan': (0,0,0,0), 'red': (0,0,0,0), 'gold': (0,0,0,0), 'white': (0,0,0,0)}
def bbox_update(cat, x, y):
    x0, y0, x1, y1 = cats[cat]
    if x0 == x1 == 0:
